window.__D("text/maamarei-admur-hazaken/c018",{"p":[[2101920340,"רחם עלינו ותן בלבינו בינה, להיות מבין<sup data-n=\"1961\">10</sup> דבר מתוך דבר, היינו להתבונן בהתהוות מאין ליש, איך שכל בריאת העולם הוא בדיבור א' כביכול כמ\"ש בדבר<sup data-n=\"1962\">11</sup> ה' כו', וכמארז\"ל במאמר<sup data-n=\"1963\">12</sup> א' יכול להבראות כו', ומבשרי אחזה כמשל באדם שדיבור א' בטל לגבי מהות הנפש, וכלא ממש חשיבי, כמ\"כ למעלה כל העולמות עליונים ותחתונים כו' הם בדיבור א' כבי' וכלא ממש חשיבי לגבי עצמותו ית', ומאריכות ההתבוננות הנ\"ל נולדה מדת אהבה בחי' אברהם ואח\"כ אברהם<sup data-n=\"1964\">13</sup> הוליד את יצחק כו', ולא נבוש כו' לעולם ועד, פי' לעולם ועד שיהי' אז התגלות אלקות כמ\"ש ונגלה<sup data-n=\"1965\">14</sup> כבוד הוי' וראו כל בשר כו', אז יהי' הבושה לעולם ועד על מעשה עוה\"ז הקשים ורעים בבחי' יש ונפרד לגמרי, דבאמת אני<sup data-n=\"1966\">15</sup> הוי' לא שניתי כו', וגם עתה אין דבר מסתיר לנגדו ית', כי אתה הוא עד שלא נברא ואתה הוא משנברא כו', ולזה היא הבושה לעולם ועד כו'.\n<b>והנה</b> אמרז\"ל סנדל<sup data-n=\"1967\">16</sup> קושר כתרים לקונו מתפלות של ישראל, הנה בלשון הגמ' נק' סנד\"ל, ובלשון המקרא נק' נעל הוא החופה<sup data-n=\"1968\">17</sup> את רוב הרגל, הוא קושר כתרים לקונו מתפלות של ישראל, מתפלות הוא בחי' שמו\"ע, כי כל הבקשות שבש\"ע חננו מאתך כו' גאלנו כו' רפאנו כו', הוא הבקשות להיות שינוי הרצון למעלה מבחי' תורה, כי אורייתא<sup data-n=\"1969\">18</sup> מחכמה נפקת כו'. והנה התהוות העולם הוא ע\"פ ד\"ת כי אין<sup data-n=\"1970\">19</sup> יסורים בלא עון, וכמ\"כ אריכות הגלות ג\"כ בוודאי עפ\"י ד\"ת, לזה אנו מבקשים שיהי' שינוי רצון גאלנו כו' למעלה מבחי' הרצון הנמשך בהתורה דמחכמה נפקת כו', היינו שיומשך מבחי' בעל הרצון כו'. והנה כדי שנוכל להתפלל ש\"ע בבקשות כנ\"ל צריך בתחלה לסמוך גאולה לתפלה הוא בחי' מס\"נ שבק\"ש שמע ישראל כו' בכל לבבך ובכל נפשך כו' פי' שמע הוא לשון התבוננות איך שהוי' אלוקינו הוי' אחד, בחי' אחדות פשוט כו', וכל העולמות הם רק בדיבור א' כנ\"ל וכלא ממש חשיבי לגבי מהותו ועצמותו כנ\"ל, ובהעמקת ההתבוננות באריכות כנ\"ל אזי נכספה וגם כלתה נפשו להיות נכלל בעצמותו ית' מי<sup data-n=\"1971\">20</sup> לי בשמים ועמך לא חפצתי בארץ, פי' ועמך אפי' כל האורות עליונים גבוה מעל גבוה כו', לא חפצתי רק ליכלל בעצמותו ומהותו ית', בחי' אחדות פשוט,",[["1961","10","<b>מבין דבר מתוך דבר</b>: חגיגה יד, א. וראה תו\"א בראשית א, א [פי' תוך דבר היינו בחי' ממכ\"ע ודבר היינו עצם בחי' המלכות שהוא סוכ\"ע]. לקו\"ת ואתחנן ו, ג. שם דרושים לש\"ש סז, ג."],["1962","11","<b>בדבר ה'</b>: תהלים לג, ו."],["1963","12","<b>במאמר א' יכול להבראות</b>: אבות פ\"ה מ\"א."],["1964","13","<b>אברהם הוליד את יצחק</b>: תולדות כה, יט. וראה תו\"א תולדות יז, ג ואילך."],["1965","14","<b>ונגלה כבוד הוי'</b>: ישעי' מ, ה."],["1966","15","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["1967","16","<b>סנדל קושר כתרים לקונו</b>: ראה זח\"א קסז, ב. מאמרי אדהאמ\"צ שמות ח\"ב ע' רמח ואילך. סה\"מ תרנ\"ו ע' שלח. סה\"מ תש\"ח ע' 202. וש\"נ."],["1968","17","<b>החופה את רוב הרגל</b>: יבמות קב, ב. וראה גם המשך תער\"ב ח\"א ע' רד."],["1969","18","<b>אורייתא מחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ובכ\"מ."],["1970","19","<b>אין יסורים בלא עון</b>: שבת נה, א."],["1971","20","<b>מי לי בשמים</b>: תהלים עג, כה."]]],[2101920341,"והיינו ע\"י והיו<sup data-n=\"1972\">21</sup> הדברים האלה אשר אנכי מצוך, שהוא ע\"י התקשרות מחשבתו ודיבורו בתורה להיות דבר ה' דבר בו כמ\"ש ואשים<sup data-n=\"1973\">22</sup> דברי בפיך וכמארז\"ל אלו<sup data-n=\"1974\">23</sup> ואלו דא\"ח כו', ואח\"כ בפ' שני' שבק\"ש כתי' ואספת<sup data-n=\"1975\">24</sup> דגנך הוא מעשה הצדקה כו', וע\"י מס\"נ שבק\"ש כנ\"ל שהוא למעלה מבחי' התורה כמבואר בכמה מקומות, וכמו שמרומז ג\"כ בגמרא יש<sup data-n=\"1976\">25</sup> קונה עולמו בשעה א' כו', שעה לשון וישע<sup data-n=\"1977\">26</sup> כו', עי\"ז נוכל אח\"כ להתפלל ש\"ע שיהי' שינוי הרצון למעלה מבחי' התורה כו'.\n<b>אך</b> מחשבתנו ודיבורנו שבתפלה היא גשמי' ואיך יכול לעורר למעלה לבחי' רצון כתר עליון כו', הוא ע\"י מלאך סנד\"ל המקבל תפלות של ישראל ומפשיטם מגשמיו' לרוחניות וקושר כתרים כו'.\n<b>והנה</b> ענין בחי' סנדל ונעל הנ\"ל, צריך להבין תחלה ענין השתלשלות העולמות והתהוות מאין ליש, דהנה באמת הגם שבחי' השתלשלות הוא ע\"י בחי' מדותיו ית' כמו יום ראשון נמשך בחי' יהי אור<sup data-n=\"1978\">27</sup> שהוא בחי' חסד עליון, וביום ב' יהי רקיע כו', עכ\"ז מהשתלשלות חסד עליון לא הי' יכול להתהוות בחי' יש ובע\"ג בבחי' נפרד, רק אדרבה הי' בבחי' ביטול לגמרי כמשל זיו השמש בשמש, אך עיקר התהוות מאין ליש הוא עפ\"י מדת מלכות כי אין<sup data-n=\"1979\">28</sup> מלך בלא עם הוא בחי' שם אלקים שהוא בחי' נרתק המכסה ומסתיר לש' הוי', כתי' כי שמש<sup data-n=\"1980\">29</sup> ומגן הוי' אלקים והוא ע\"י כי<sup data-n=\"1981\">30</sup> הוא צוה ונבראו כו', דבר המלך שלטון שהוא בחי' ציווי המלך כו', אך עכ\"ז הי' העולם מתפשט בלי גבול וקץ, ושיהי' התהוות בבחי' גבול מהלך<sup data-n=\"1982\">31</sup> ת\"ק שנה כו' הוא ע\"י המלאך סנד\"ל שהוא בחי' נעל החופה את רוב הרגל בחי' מל' הנ\"ל, וכמ\"ש והארץ<sup data-n=\"1983\">32</sup> הדום רגלי הוא החופה את בחי' מל' הנ\"ל, להיות בבחי' גבול מהלך ת\"ק שנה, והוא ע\"י בחי' המלאכים שהם בחי' יש, והם בבחי' ביטול ואינם בבחי' נפרד כלל, וכמ\"ש וצבא<sup data-n=\"1984\">33</sup> השמים לך משתחוים כו', ולזה כוחו רב ועצום להיות קושר כתרים לקונו, והיינו ע\"י כי נעוץ<sup data-n=\"1985\">34</sup> תחילתן בסופן, וסוף<sup data-n=\"1986\">35</sup> מעשה במחשבה תחלה, והיינו במחשבה הקדומה אנא<sup data-n=\"1987\">36</sup>",[["1972","21","<b>והיו הדברים האלה</b>: ואתחנן ו, ו."],["1973","22","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["1974","23","<b>אלו ואלו דא\"ח</b>: עירובין יג, ב."],["1975","24","<b>ואספת דגנך</b>: עקב יא, יד."],["1976","25","<b>יש קונה עולמו בשעה א'</b>: ע\"ז י, ב. יז, א. ועוד."],["1977","26","<b>וישע כו'</b>: בראשית ד, ד."],["1978","27","<b>יהי אור . . יהי רקיע</b>: בראשית א, ג. ו."],["1979","28","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. ר\"פ בלק. עמק המלך ש\"א רפ\"א. תניא שעהיחוה\"א רפ\"ז. וראה בהמ\"מ בס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תרלא."],["1980","29","<b>שמש ומגן הוי' אלקים</b>: תהלים פד, יב. וראה תניא שעהיחוה\"א פ\"ד. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתקב."],["1981","30","<b>כי הוא צוה ונבראו</b>: תהלים קמח, ה."],["1982","31","<b>מהלך ת\"ק שנה</b>: חגיגה יג, א."],["1983","32","<b>והארץ הדום רגלי</b>: ישעי' סו, א."],["1984","33","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["1985","34","<b>נעוץ תחילתן בסופן</b>: ס' יצירה פ\"א מ\"ז."],["1986","35","<b>וסוף מעשה במחשבה תחלה</b>: פיוט ”לכה דודי\"."],["1987","36","<b>אנא אמלוך</b>: מובא בכ\"מ בשם האד\"ר. וראה בהמ\"מ במאמרי אדהאמ\"צ דברים ח\"ג ע' תתצד."]]],[2101920342,"אמלוך כו' בחי' מל' דא\"ס כי עיקר תכלית הבריאה הי' להיות בחי' יש ובטל אליו ית'.\n<b>וכמ\"כ</b> למטה בנפש האדם שבחי' נפש הבהמיות הוא הנמשך משמרי אופנים כי בחי' המרכבה פני ארי' הוא בחי' אהבה, פני שור בחי' יראה, והן נושאים את הכסא, ומזיעתן<sup data-n=\"1988\">37</sup> של חיות היינו שא\"א להם לסבול עול עוצם האהבה והפחד הנמשך בהם לזה והחיות<sup data-n=\"1989\">38</sup> זעות מחיל כו', הוא בחי' פסולת הנמשך מהם כמשל הזיעה היוצא דרך נקבי העור, אך מהעור עצמו הוא בחי' חיצונית של דחילו ורחימו של החיות שבמרכבה והן בחי' אותיות וכו', מהן נמשך למטה (וע\"י השתלשלות ובחי' נוגה תערובות טוב ורע וכו' כנודע) נפש הבהמיות והטבעיות, ואין כל הטבעיות שוין כי יש טבעו אוהב כבוד או ממון כו'. והנה כמשל הבהמה שבשר גידים ועצמות הוא הפנימי' שלה והעור החיצון הוא מלביש אותה ומהעור עושים מנעלים, וכמ\"כ בנפש הבהמות הנמשך מבחי' חיצוני' של אופנים שבמרכבה הנ\"ל, ע\"י אתכפיא ואתהפכא של בחי' נפש הבהמי' הנ\"ל במס\"נ שבק\"ש בכל<sup data-n=\"1990\">39</sup> לבבך בשני יצריך כו', נעשה בחי' נעל החופה את רוב הרגל דעיקר ההילוך הוא ברגל שמוליך גם את הראש, כך ע\"י אתכפיא ואתהפכא של בחי' נפש הבהמיות הנ\"ל במס\"נ בק\"ש שהוא בחי' סוף מעשה הוא במח' תחלה, כי תכלית המכוון הוא להיות דירה בתחתונים כנ\"ל, ועי\"ז נוכל אח\"כ להתפלל בש\"ע שיהי' שינוי רצון מבחי' כתר עליון למעלה מבחי' התורה כנ\"ל.\n<b>והנה</b> בתפלה יש ג' מדריגות כנגד ג' עולמות בי\"ע, והיינו תחלת התפלה הוא עליות עולם העשי' ברוך אתה כו' שלא עשני כו', ואח\"כ קטורת ואח\"כ ברוך שאמר ופסד\"ז הללוי' הללו<sup data-n=\"1991\">40</sup> לשון בהילו כו', י\"ה בחי' חו\"ב היינו שמאיר בחי' חו\"ב שלא<sup data-n=\"1992\">41</sup> יהי' בחי' טמטום המוח וטמטום הלב כו', שהוא ההתבוננות איך שכל העולמות הם רק זכר מבחי' רב טוב כו', כמ\"ש זכר<sup data-n=\"1993\">42</sup> רב טובך, ולהודיע<sup data-n=\"1994\">43</sup> לבני האדם גבורותיו, הן בחי' הצמצומים אבל לגבי מהותו ועצמותו ית' כלא חשיבי, ויחיד חי עולמים מלך עד ברכו יוצר אור הכל הוא תפלת היצירה, שהוא",[["1988","37","<b>ומזיעתן של חיות</b>: חגיגה יג, ב."],["1989","38","<b>והחיות זעות מחיל כסא</b>: ע\"פ פיוט ”והחיות\" במוסף לר\"ה (בקדושה נוסח אשכנז)."],["1990","39","<b>בכל לבבך בשני יצריך</b>: ואתחנן ו, ה. ברכות נד, א. ספרי עה\"פ. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תסב וע' שעט."],["1991","40","<b>הללו לשון בהילו</b>: איוב כט, ג. וראה תו\"א מקץ לו, א. לקו\"ת נצבים נא, ד. לקו\"ת שה\"ש מח, ג."],["1992","41","<b>שלא יהי' בחי' טמטום המוח וטמטום הלב</b>: ראה ד\"ה לה\"ע טמטום הלב, בס' מאמרי אדה\"ז הקצרים ע' תפב ואילך. וראה עוד ע\"ז בהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"ב ע' תקס ואילך."],["1993","42","<b>זכר רב טובך</b>: תהלים קמה, ז."],["1994","43","<b>ולהודיע לבני האדם גבורותיו</b>: שם, יב."]]],[2101920343,"עליות עולם היצירה, ואח\"כ ברכו יוצר אור שהוא תפלת עולם הבריאה, והאופנים וחיות כו' ברעש כו' איך שהוא לבדו מרום וקדוש כו', ואח\"כ בחי' ק\"ש בכל לבבך כו' ואח\"כ תפלת ש\"ע בלחש בחי' אצילות כו', ועלית כל תפילות ימות החול הוא בשבת שהוא עליות העולמות, כמ\"ש עולת<sup data-n=\"1995\">44</sup> שבת בשבתו, כי בו שבת כו', לכך בשבת ויו\"ט מותר בנעילת הסנד\"ל שגם בחי' נעל שהוא בחי' נפש הבהמיות נתעלה בשבת, לכך מצוה לאכול בשבת כמארז\"ל במה<sup data-n=\"1996\">45</sup> מענגו כו', משא\"כ ביוה\"כ שאסור באכילה ושתי' אסור בנעילת הסנד\"ל.\n<b>והנה</b> בעליות נפש הבהמיות בשבת ע\"י אתכפיא ואתהפכא שבימות החול בתפלה כו', ע\"ז נאמר מה יפו פעמיך בנעלים שגם הנעלים הם יפים ואדרבה עיקר היופי הוא בנעלים, כי סוף מעשה במחשבה תחלה, וזהו תכלית בריאת העולמות כו'. אך שלהיות בכוחינו למסור<sup data-n=\"1997\">46</sup> נפשו באחד הוא ע\"י הארת והמשכת חסד עליון הבא מלמעלה. וזהו בת<sup data-n=\"1998\">47</sup> נדיב בתו של אברהם אבינו, שנק' נדיב שנתן<sup data-n=\"1999\">48</sup> מלחמו גם לערבים, ולמעלה הוא בחי' הארת<sup data-n=\"2000\">49</sup> חסד עליון הנמשך למטה בכל יום בבקר כמ\"ש וישכם אברהם בבקר ויחבוש את חמורו כדי שנוכל להתפלל בבקר כי כל ההתחלות קשות ומה גם בעמדו משינתו<sup data-n=\"2001\">50</sup> שהוא א' מס' כו', הוא ע\"י הארת והמשכת חסד עליון הבא מלמעלה כנ\"ל.\n<b>חמוקי</b><sup data-n=\"2002\">51</sup> ירכיך כמו חלאים מעשי ידי אמן, פי' ירכים<sup data-n=\"2003\">52</sup> הם לבר מגופא שהיא התורה שנק' גופא, ובחי' ירכי' שלבר מגופא הוא בחי' מעשה הצדקה שהוא ע\"י עשי' גשמי' שברגלים<sup data-n=\"2004\">53</sup> שהולך בעסקי מו\"מ ואח\"כ נותן מיגיעת כפו כו', אך<sup data-n=\"2005\">54</sup> ברגלים יש ג' פרקי, פרק העליון הוא הנק' בשם ירכים שהוא בסתר, כך הוא עיקר מצות הצדקה הוא מתן בסתר. כמו חלאים, פי' חלאים הוא תכשיטי אשה שעל הראש כמ\"ש וחלי<sup data-n=\"2006\">55</sup> כתם, ובלשון המשנה טוטפת<sup data-n=\"2007\">56</sup> וסרביטין, והיינו ע\"י",[["1995","44","<b>עולת שבת בשבתו, כי בו שבת</b>: פינחס כח, י. בראשית ב, ג."],["1996","45","<b>במה מענגו</b>: שבת קיח, ב."],["1997","46","<b>למסור נפשו באחד</b>: ראה זח\"ב קיט, א. זח\"ג לג, א. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ב ע' תו."],["1998","47","<b>בת נדיב בתו של אברהם אבינו</b>: סוכה וחגיגה ושהש\"ר שם (נסמן בתחילת המאמר)."],["1999","48","<b>שנתן מלחמו גם לערבים</b>: ראה סוטה י, א ואילך. ב\"מ פו, ב."],["2000","49","<b>הארת החסד עליון הנמשך למטה בכל יום בבקר כמ\"ש וישכם אברהם בבקר</b>: וירא יט, כז. כא, יד. כב, ג. ראה תקו\"ז תכ\"ב (סז, א). זח\"ב קיט, ב. זח\"ג סד, ב."],["2001","50","<b>משינתו שהוא א' מס'</b>: ברכות נז, ב. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ ח\"ב ע' תרא."],["2002","51","<b>חמוקי ירכיך</b>: שה\"ש ז, ב (המשך פסוק: מה יפו פעמיך בנעלים)."],["2003","52","<b>ירכים הם לבר מגופא</b>: זח\"א כא, ב. ועוד."],["2004","53","<b>שברגלים שהולך</b>: בכת\"י ב: שהולך ברגליו."],["2005","54","<b>אך ברגלים יש ג' פרקי</b>: ראה זח\"א רמא, א. לעיל במאמר ד\"ה לה\"ע קי\"ס. שער האמונה לאדהאמ\"צ פנ\"ה."],["2006","55","<b>וחלי כתם</b>: משלי כה, יב."],["2007","56","<b>טוטפת וסרביטין</b>: שבת נז, א."]]],[2101920344,"מעשה הצדקה מלמטה נעשה מזה בחי' תכשיטי' ועטרה שעל הראש כמ\"ש וילבש צדקה כו' כובע ישועה בראשו כי למעלה נאמר ראשו<sup data-n=\"2008\">57</sup> כתם פז קווצותיו תלתלים כו', הוא בחי' תושב\"כ ותושבע\"פ והוא בחי' תכשיטי איש וע\"י מעשה הצדקה נעשה תכשיטי אשה, והוא ע\"י מעשי ידי אמן, כמו אומן המלבן ומצרף מעפר ואדמה להיות תכשיט ליופי כמ\"כ ע\"י מעשה הצדקה מיגיעו ועסקו במו\"מ ועם גוים כו' ואח\"כ נותן מיגיעו לעני להחיות רוח שפלים הוא הבחי' הבירור והצירוף שנעשה בחי' תכשיטי אשה ואין תכשיט אלא ליופי, עי\"ז נמשך אהבה מלמעלה ונעשה בחי' יחוד קוב\"ה ושכינתי' להיות כי כל האומר<sup data-n=\"2009\">58</sup> אין לי אלא תורה אפי' תורה אין לו כי מה שייכות יש לו עם התורה להמשיך בחי' התורה ח\"ע להיות בפיו דא\"ח והיינו להיות בחי' אלקים שהוא בחי' הצמצום בבחי' חיי' רוחני' מחיי' החיים א\"ס ב\"ה, אך ע\"י מעשה הצדקה למטה להחיות רוח שפלים באתעדל\"ת אתעדל\"ע לעורר מלמעלה ג\"כ בחי' המשכת התורה למטה. וז\"ש תען<sup data-n=\"2010\">59</sup> לשוני אמרתיך כי כל מצותיך צדק, פי' שלהיות תען לשוני אמרתיך מלשון עונה<sup data-n=\"2011\">60</sup> אחריהם מה שהם אומרים בפ\"ג דסוכה שהוא בחי' המשכת התורה מלמעלה למטה שהיא בחי' תר\"ך עמודי אור, כמשל עמוד שמחבר מעלה ומטה הוא ע\"י כי כל מצותיך צדק, והיינו ע\"י מצות<sup data-n=\"2012\">61</sup> מעשיות שנק' בשם צדקה כמ\"ש וצדקה תהי' לנו כי נשמור לעשות כו' כל החוקים כו'.\n<b>אך</b> הנה פסוק הזה נאמר גם על בחי' התורה כמארז\"ל אף<sup data-n=\"2013\">62</sup> ד\"ת בסתר כו', והיינו כי בחי' התורה נמשך למטה בבחי' גשמיות זרעים ותרומה כו'. והנה יש ב' בחי' מנעלים, נעל א' הוא עליות נפש הבהמיות ע\"י עשיות כל המצות וצדקה כנגד כולן הנמשך מבחי' גבריאל במרכבה בחי' יראה ופחד, ונעל הב' הוא בחי' שמחה של מצוה שהוא ג\"כ מבחי' נפש הבהמיות כמ\"ש בשמחה<sup data-n=\"2014\">63</sup> בטוב לבב שעיקר השמחה הוא בלב ששם משכן נפש הבהמיות כי<sup data-n=\"2015\">64</sup> הדם הוא הנפש וכנודע<sup data-n=\"2016\">65</sup> מספרי הטבעיי' שעצבות הוא מעכירת הדם שבלב כשהוא עכור, והשמחה הוא כשהדם צלול והוא ע\"י אשר קדשנו במצותיו אשר לשון תענוג",[["2008","57","<b>ראשו כתם פז</b>: שה\"ש ה, יא."],["2009","58","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["2010","59","<b>תען לשוני אמרתך</b>: תהלים קיט, קעב. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' א'ע."],["2011","60","<b>עונה אחריהם מה שהם אומרים בפ\"ג דסוכה</b>: לח, א (במשנה)."],["2012","61","<b>מצות מעשיות שנק' בשם צדקה כמ\"ש וצדקה תהי' לנו</b>: ואתחנן ו, כה. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"ב ע' שעא."],["2013","62","<b>אף ד\"ת בסתר</b>: סוכה מט, ב: מאי דכתיב חמוקי ירכיך למה נמשלו דברי תורה לירך לומר לך מה ירך בסתר אף ד\"ת בסתר כו'."],["2014","63","<b>בשמחה ובטוב לבב</b>: תבוא כח, מז."],["2015","64","<b>כי הדם הוא הנפש</b>: פ' ראה יב, כג."],["2016","65","<b>וכנודע מספרי הטבעי'</b>: בס' מאמרי אדהאמ\"צ נ\"ך ע' שכו שם: וכידוע בס' הרפואה שהעצבות והמרה שחורה באה מסיבת קלקול הדמים בפסולת העכור שבדם שבלב כמו המרירות שמקלקלת הדמים עד שנעשה דם שחור כו' והשמחה באה מצד צלילות הדמים ונקיותם כו'."]]],[2101920345,"העליון קדשנו במצותיו כו' וכל המצות צריך לעשות בשמחה כמ\"ש תחת אשר לא עבדת בשמחה ובצדקה נאמר ג\"כ אל<sup data-n=\"2017\">66</sup> ירע לבבך בתתך לו הוא בחי' נעל הב' של בחי' נפש הבהמיות הנמשך ממחנה מיכאל בחי' אהבה.",[["2017","66","<b>אל ירע לבבך</b>: ע\"פ ראה טו, י. וראה גם ס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתקסו."]]],[2101920346,"<h3>להבין ביאור הדברים</h3>\n<b>ביאור על הנ\"ל</b>\n<b>להבין</b><sup data-n=\"2018\">1</sup> ביאור הדברים ענין מה יפו פעמיך בנעלים כו'. הנה ידוע שתכלית בריאת העולמות הי' להיות לו דירה בתחתונים דהיינו שיהי' גילוי אלקות בחי' סתימא<sup data-n=\"2019\">2</sup> דכל סתימין וכו', וכמו למשל מבשרי אחזה באדם למטה שגילוי חכמתו ושכלו הוא מתגלה בדיבור כו', כמ\"כ למעלה בא\"ס ב\"ה שכדי שיהי' גילוי א\"ס בחי' סתימא דכל סתימין הוא דוקא ע\"י בחי' מל' כי אין<sup data-n=\"2020\">3</sup> מלך בלא עם, כי עיקר התענוג למעלה הוא דוקא ע\"י שנתגלה למטה בבחי' נפרד ויש גמור והיש בטל אליו ית' כמו וצבא<sup data-n=\"2021\">4</sup> השמים לך משתחוים כו', וכמו למשל באבנים טובות כשהם בהסתר ובבית אפל אין מהם שום תענוג כ\"א כאשר הם בהתגלות לעין כל שמאירים אזי מקבלים מהם תענוג ושעשועים מבהירותם, כמ\"כ למעלה עיקר התענוג הוא ע\"י הגילוי למטה בבחי' מל' אין מלך בלא עם כנ\"ל. והנה לכאורה קשה איך שייך לומר שהגילוי סתימא וכו' הוא ע\"י בחי' מל' הלא כתיב כי<sup data-n=\"2022\">5</sup> שמש ומגן הוי' אלקים שבחי' שם אלקים שהוא בחי' מל' הוא בחי' מגן ונרתק לשם הוי' ב\"ה לצמצם ולהעלים את בחי' הגילוי של הוי' ואיך שייך לומר שהגילוי הוא ע\"י בחי' מל'. אך כתיב ה'<sup data-n=\"2023\">6</sup> מלך גאות לבש, פי' שיהי' ה' מלך גאות הוא ע\"י לבוש שהוא ע\"י ההסתר שהוא מסתתר בבחי' יש ודבר לצמצם ולהעלים אור א\"ס ואח\"כ נעשה בחי' הביטול אז מתגלה אור א\"ס בבחי' גילוי גמור יותר מכמו שהוא לבוש כו' כמו למשל באבנים טובות כמו שית' וכו'.",[["2018","1","<b>להבין ביאור הדברים</b>: נדפס כאן מכת\"י מניח שרשם בעת שמיעת המאמר מכ\"ק אדה\"ז [כת\"י מס' 1113 מט, א. ואין ברור מן הכת\"י אם הוא אותו מניח של גוף המאמר ד\"ה מה יפו דלעיל]. וראה ביאור זה באיזה שינויים בס' מאמרי אדה\"ז כתובים ח\"ב ע' קפ. ובאריכות בס' מאמרי אדהאמ\"צ נ\"ך ע' שכח ואילך. ובשינויים והגהות באוה\"ת שה\"ש ח\"ב ס\"ע תקפט ואילך (שם רק חלק מהמאמר). ח\"ג ע' תתקצג."],["2019","2","<b>סתימא דכל סתימין</b>: זח\"ב פט, א. קמו, ב."],["2020","3","<b>אין מלך בלא עם</b>: נסמן לעיל בהמאמר."],["2021","4","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["2022","5","<b>כי שמש ומגן הוי' אלקים</b>: תהלים פד, יב."],["2023","6","<b>ה' מלך גאות לבש</b>: תהלים צג, א. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ נ\"ך ע' יד."]]],[2101920347,"ב) <b>והנה</b> בחי' מל' כלול מי' ספי' וע\"ז קאי כל המזמור ך\"א שבתהלים, ה' בעזך ישמח מלך שהוא בחי' גבו' שבמל', ובישועתך בחי' חסדים כו', תשית לראשו עטרת פז בחי' כתר שבמל'. דהנה אין<sup data-n=\"2024\">7</sup> אשה אלא ליופי, דהיינו ע\"י קישוטי אשה שמתקשטת אזי מקבל הבעל תענוג שיהי' עי\"ז בחי' יחוד כו'. כמ\"כ למעלה הנה כתיב ותקם<sup data-n=\"2025\">8</sup> בעוד לילה ותתן טרף שבחי' מל' יורדת בכל לילה לבי\"ע לברר בירורים כו'. וביום הוא בחי' עליות המל' בתפלה ע\"י מס\"נ בכל<sup data-n=\"2026\">9</sup> לבבך. וכל התפלות שבחול מתעלים בשבת שהוא בחי' עליות העולמות. ובעליות המל' כנ\"ל בבחי' א\"ח הוא גבוה מאד נעלה למעלה בבחי' כתר עליון בחי' מח' הקדומה אנא אמלוך, כי בבחי' אור ישר נמנה המל' ממדריגה האחרונה כמבואר בע\"ח, כתר חב\"ד חג\"ת נהי\"ם, אבל בעליות בבחי' אור חוזר בחי' המל' הוא בבחי' כתר כמו יתנו לך כתר מלוכה כתר מלכות, שבחי' כתר רצון הקדום מאיר בבחי' מל', והיינו סוף מעשה במחשבה תחלה, היינו שע\"י מעשה התחתונים אתכפי' ואתהפכא שהוא בחי' קישוטי אשה, שהוא בחי' הבירורים שנתברר הרע לטוב, דהיינו שבחי' היש בטל אליו ית', הוא עיקר התענוג שעלה ברצונו ית' להיות לו דירה בתחתונים ע\"י<sup data-n=\"2027\">10</sup> גילוי סתימא דכל סתימין מחשבה הקדומה כו'. ובתחלת הבריאה הי' ע\"י שעלה ברצונו הפשוט בחי' העלאת מ\"ן מיני' ובי', דהיינו שכך עלה ברצונו הפשוט שיקבל תענוג ממעשה התחתונים ע\"י העלאת מ\"ן שלהם בבחי' ביטול אתכפי' וכו', ואח\"כ<sup data-n=\"2028\">11</sup> תלוי במעשה התחתונים שע\"י אתעדל\"ת אתעדל\"ע להיות תשית לראשו עטרת פז בחי' כתר מל' ע\"י עליות המל' בבחי' אור חוזר מבירורים דבי\"ע וזה נעשה עטרה וכו'.\nג) <b>ועתה</b> יש להבין מה שנק' מל' בחי' נעל, כמו<sup data-n=\"2029\">12</sup> שמבואר בע\"ח ופרד\"ס שיש בחי' נעל דבריאה ונעל דיצירה ונעל דעשי' כו'. ולהבין כ\"ז צריך להבין מה שיש בחי' אותיות השכל ואותיות הדיבור שהן בחי' חיצוניות ודבר נפרד וזר לגמרי, כמו השכל בהתלבשותו באותיות המחשבה שהן דבר זר לגבי עצם השכל שהוא בחי' השכלה עצמי' שאינו בגדר אותיות כלל רק כשצריך להתגלות השכל לזולתו מלבישו באותיות שהם בחי' חיצוניות ודבר זר ואינן מערך השכל כלל, ולא כדוגמת המדות הנמשכים מהשכל בבחי' חיצונית ע\"י השתלשלות מבחי' נה\"י שבשכל, עכ\"ז אינן דבר נפרד וזר לגבי השכל רק אדרבה",[["2024","7","<b>אין אשה אלא ליופי</b>: ראה תענית לא, א."],["2025","8","<b>ותקם בעוד לילה</b>: משלי לא, טו. וראה ב”מילואים להמ\"מ\" בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"א ע' שג. ובמ\"מ בס' מאמרי אדהאמ\"צ בראשית ע' קמו."],["2026","9","<b>בכל לבבך</b>: ואתחנן ו, ה."],["2027","10","<b>ע\"י</b>: תיבה זו אינה ברורה בהכת\"י. ואוצ\"ל: בחי'."],["2028","11","<b>ואח\"כ תלוי במעשה התחתונים</b>: ראה ע\"ח שער דרושי הנקודות (ש\"ח) ספ\"ו. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תתמג."],["2029","12","<b>כמו שמבואר בע\"ח ופרד\"ס שיש בחי' נעל דבריאה ונעל דצירה ונעל דעשי'</b>: ראה ע\"ח שער החשמל (שמ\"א) פ\"א ופ\"ב. דרושי כללות אבי\"ע (שמ\"ב) פי\"ג. אוה\"ת שה\"ש ע' תקצא. וע' תתקצד. וראה פרדס שט\"ז (שער אבי\"ע) פ\"ד."]]],[2101920348,"מעצם השכל נתהווה המדה, כמו שאנו רואים בתינוק שמדותיו הם בקטנות מחמת קטנות השכל וכל מה שיגדל יותר יגדל כח השכל וכו'. אבל בחי' אותיות המחשבה הן בחי' לבושים חיצונים ודבר זר ונפרד לגמרי לגבי השכל, וכמ\"כ באותיות הדיבור בה' מוצאות אחה\"ע כו' א\"א לומר שהאותיות מתהווים ע\"י הה' מוצאות כמו בקמיצת השפתים, כי מה שייכות יש לה' מוצאות עם האותיות עד שע\"י יתהווה, והראי' בתינוק שיש בו ג\"כ ה' מוצאות ואינו יכול לדבר, אלא מוכרח לומר שיש בחי' אותיות הקבועים בנפש עצמו כמ\"ש ויהי<sup data-n=\"2030\">13</sup> האדם לנפש חי', ותרגם לרוח ממללא, רק ששם הם ברוחניות ומיוחדים בנפש בלי התחלקות רק אח\"כ ע\"י התגלותן בהבל הלב להיות גילוי לזולתו ודיבור, אז נתחלקים לה' מוצאות אחה\"ע<sup data-n=\"2031\">14</sup> וכו' בומ\"ף ממוצא אחר כו'. נמצא שבחי' אותיות הדיבור הגשמי הנמשכים בה' מוצאות הם בחי' לבוש חיצוני ונפרד לגמרי לגבי עצם האותיות הקבועים בנפש עצמה ואינן מערכן ודוגמתן כלל. ומכ\"ז מובן שיש בחי' אותיות השכל ואותיות הדיבור שהן דבר נפרד לגמרי לגבי השכל ואותיות הנפש, רק שהם מלבישים את השכל ואותיות הרוחני' בנפש וכו'. ואותיות האלו נק' נעלים כמו נעל שנעשה מבחי'<sup data-n=\"2032\">15</sup> עור החיצון רק שמלביש את הרגל, כמו\"כ למעלה נעל דבריאה הוא בחי' אותיות השכל שהוא בחי' מלאכים דבריאה, ונעל דיצירה הוא בחי' אותיות הדיבור שהן בחי' מלאכים דיצירה מט\"ט כו', נעל דעשי' הוא ג\"כ בחי' אותיות הדיבור והוא בחי' מלאכים דעשי' בחי' סנדל כו', וכמבואר במ\"א שיש ב' בחי' אותיות הדיבור א' בחי' אותיות שהם בהתחלקות ו\"ק והם הנק' אותיות דיצירה כמבואר<sup data-n=\"2033\">16</sup> בע\"ח ז\"א מקנן ביצירה, והב' בחי' אותיות הדיבור בלי התחלקות ו\"ק, והוא בחי' אותיות דעשי' מל' מקנן בעשי', ואתעבידת נקודא חדא וכמ\"ש אופן<sup data-n=\"2034\">*16</sup> אחד בארץ כו'.\nד) <b>ולהבין</b> מה שנק' המלאכים בכל עולם בשם נעל, דהנה גם למלאכים יש ג\"כ גופים נפרדים מורכבים מאש רוח כמ\"ש עושה<sup data-n=\"2035\">17</sup> מלאכיו רוחות משרתיו אש לוהט, שהם בחי' חיצוניות ונפרד לגמרי לגבי נשמת רוח ה' אשר בקרבם, שהוא בחי' השגת אהוי\"ר שלהם, כמו מחנה מיכאל באהבה ומחנה גבריאל יראה ופחד ה' וכו', והגוף שלהם הוא גשמי ועור חיצון לגמרי כמ\"ש",[["2030","13","<b>ויהי האדם לנפש חי'</b>: בראשית ב, ז."],["2031","14","<b>אחה\"ע וכו' בומ\"ף ממוצא אחר</b>: ראה ס' יצירה פ\"ב מ\"א. ובהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' קה."],["2032","15","<b>מבחי' עור החיצון</b>: ראה גם ס' מאמרי אדהאמ\"צ דרושי חתונה ח\"א ע' פה. דברים ח\"ג ע' תתקכג. וש\"נ."],["2033","16","<b>כמבואר בע\"ח ז\"א מקנן ביצירה</b>: ע\"ח שער דרושי אבי\"ע (שמ\"ב) פי\"ג. וראה תקו\"ז ת\"ו (כג, א). תניא פל\"ט."],["2034","*16","<b>אופן אחד בארץ</b>: יחזקאל א, טו. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"ג ע' תקתנא."],["2035","17","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד. וראה סידור עם דא\"ח ערה, ד (בשם ס' הגמול להרמב\"ן). מאמרי אדהאמ\"צ בראשית ע' קיב. נ\"ך שם ע' שלה. וש\"נ."]]],[2101920349,"והחיות<sup data-n=\"2036\">18</sup> זעות מחיל כסא, מזיעתן<sup data-n=\"2037\">19</sup> של חיות, וכמשל הזיעה שיוצא דרך נקבי עור החיצון, וכמ\"כ למעלה במלאכים ע\"י שאינן יכולים לסבול גודל עוצם אור האהבה והפחד שלהם שמצד השגתם נמשך מהם זיעה ופסולת ע\"י העור<sup data-n=\"2038\">20</sup> שלהם שנק' בחי' עור החיצון. דהנה יש בשר גידים ועצמות, שהוא בחי' ראש תוך סוף, שעצמות הם בחי' העצם והבשר הוא החופה עליהם והגידים הוא המחבר ונקרא רת\"ס, וכמו כן במדות יש ג\"כ ראש תוך סוף, חב\"ד וחג\"ת ונה\"י, ובחי' עור הוא בחי' חיצונית המקיף עליהם. וכמו כן במלאכים נק' גופים שלהם המורכבים מאש רוח, בשם עור שהוא דבר חיצון ונפרד לגמרי. אך עכ\"ז אף שהם גופים נפרדים הם בבחי' ביטול אליו ית' בתמידיות ומהפכים מיש לאין, כמ\"ש וצבא השמים לך משתחוים, לזה הם נק' בחי' נעל<sup data-n=\"2039\">21</sup> החופה את רוב הרגל שהוא בחי' מל', שע\"י ביטולם נמשך בחי' מל' דאצי' לבי\"ע, להיות בחי' בע\"ג מהלך<sup data-n=\"2040\">22</sup> ת\"ק שנה, דהיינו ע\"י עבודתם בתמידות בבחי' ביטול היש לאין, כי זהו עיקר התענוג למעלה שיהי' בחי' יש ובטל כו' נעוץ סופן בתחלתן וכו'.\nה) <b>וכמו\"כ</b> בנפש יש ג\"כ בחי' ג' נעלים הנ\"ל, דהנה בחי' נפש האלקית שבישראל הוא למעלה מבחי' נשמות המלאכים, והוא הנמשך מבחי' מחשבה עילאה, ישראל<sup data-n=\"2041\">23</sup> עלו במחשבה, ונפש הבהמית הוא הנמשך מהחיות שבמרכבה והיינו מבחי' עור החיצון שלהם בחי' אותיות כנ\"ל, ונמשך למטה להיות מדות טבעי' כבוד וכו', בחי' חיצוניות יש ונפרד לגמרי, ורק שע\"י אתכפיא ואתהפכא בבחי' ביטול היש כו' נעשה בחי' נעל כו'. ויש ג' בחי' נעל, א' בחי' נעל דבריאה, והוא בחי' שמחה של מצוה, כי שמחה היא מבחי' נפש הבהמיות הבא בגילוי בלב, שהתענוג שהוא במוח הוא בהעלם אבל גילוי התענוג הוא שמחת הלב שבנפש הבהמיות, והוא ע\"י שמחה של מצוה כו'. נעל דיצירה הוא בחי' אתכפיא ואתהפכא של נפש הבהמית שבתפלה במס\"נ בכל לבבך כו'. ונעל דעשי' הוא מעשה הצדקה כמו שית' למטה.\nו) <b>וזהו</b> סנדל<sup data-n=\"2042\">24</sup> קושר כתרים לקונו מתפלותיהן של ישראל, שהוא בחי' ש\"ע שהבקשות הוא שיהי' שינוי רצון למעלה מבחי' התורה, והיינו ע\"י בחי' הביטול שלהם כמ\"ש וצבא השמים לך משתחוים ועתה<sup data-n=\"2043\">25</sup> אלקינו מודים אנחנו לך, מודים הוא בחי' הודאה משמע שיש מחלוקת בזה. אך הנה מלמטה למעלה נקרא ההשתלשלות מאין ליש, שכל מה שלמטה נק' בחי' יש ומעלה נק' בחי' אין, כמ\"ש והחכמה<sup data-n=\"2044\">26</sup> מאין תמצא, שמציאות החכמה נק' ג\"כ יש לגבי למעלה",[["2036","18","<b>והחיות זעות מחיל כסא</b>: ע\"פ פיוט ”והחיות\" במוסף לר\"ה (בקדושה נוסח אשכנז)."],["2037","19","<b>מזיעתן של חיות</b>: חגיגה יג, ב."],["2038","20","<b>העור</b>: תיבה זו אינה ברורה בהכת\"י. ואוצ\"ל בגוף."],["2039","21","<b>נעל החופה את רוב הרגל</b>: יבמות קב, ב. וראה גם המשך תער\"ב ח\"א ע' רד."],["2040","22","<b>מהלך ת\"ק שנה</b>: ראה חגיגה יג, א-ב."],["2041","23","<b>ישראל עלו במחשבה</b>: ב\"ר פ\"א, ד."],["2042","24","<b>סנדל קושר כתרים לקונו</b>: נסמן לעיל בהמאמר."],["2043","25","<b>ועתה אלקינו מודים אנחנו לך</b>: דברי הימים א כט, יג."],["2044","26","<b>והחכמה מאין תמצא</b>: איוב כח, יב."]]],[2101920350,"מהחכמה שהוא בחי' אין, וכמ\"כ למעלה מעלה עד רום המעלות נמשך מאין ליש כו', אבל מלמעלה למטה הנה כתיב הנה<sup data-n=\"2045\">27</sup> מקום אתי, שהוא ית' מקומו של עולם והוא ית' יש אמיתי וכולא קמי' כלא ממש חשיבי, וכמשל<sup data-n=\"2046\">28</sup> המבואר בכהאריז\"ל עפ\"י גילוי אלי' שכל העולמות הם לגבי אוא\"ס ב\"ה כטיפה בים אוקינוס, והיינו כמשל הטיפה שבטילה ומתאחדת ממש בים והיו לאחדים ואיננה בבחי' נפרד בפ\"ע כלל להיות מכונה בשם דבר מה כו', ולא כמו המבואר בהמקובלים האחרונים שביטול כל העולמות לגבי אא\"ס ב\"ה הוא כמשל גרגיר חרדל שהגם שהגרגיר חרדל אין ערוך כלל וכלל לגבי גלגל החמה כו', עכ\"ז הוא במציאות ודבר מה יש ונפרד כו', אבל למעלה כבי' כל העולמות בטלים אליו ית' והם כלא ואין ואפס ממש נחשבו ואינן בבחי' נפרד ומהות דבר מה כלל וכלל.\n<b>וזהו</b> בחי' הודאה מודים אנחנו לך, היינו שאנו מודים לך שהוא מקומו של עולם כו', וכל הנמצאים מאתו ית' כלא ממש חשיבי בבחי' אין ואפס, ולזה הם תמיד בבחי' ביטול בא\"ס, וע\"י בחי' ביטול הנ\"ל מעוררים למעלה בחי' כתר עליון להיות בחי' שינוי הרצון למעלה מבחי' התורה, רפאינו, גאלינו, שעפ\"י תורה אורייתא<sup data-n=\"2047\">29</sup> מחכמה נפקת אין<sup data-n=\"2048\">30</sup> יסורים בלא עון ואריכות הגלות, אבל שיהי' יה\"י רצון מבחי' כתר עליון למעלה מבחי' רצון הנמשך בהתורה, דהנה בתורה יש מ\"ט<sup data-n=\"2049\">31</sup> פנים טמא מ\"ט פנים טהור, כמו ב\"ש<sup data-n=\"2050\">32</sup> אוסרים וב\"ה מתירים, ואלו ואלו דא\"ח, דהיינו שבדבר א' יש סברה להטות לזכות ולחוב ואלו ואלו דא\"ח, והיינו מבחי' בעל הרצון שהוא למעלה מבחי' הרצון שמלובש בהתורה שהוא בחי' רצון דחכמה שיכול להיות שאותו הדבר עצמו יתהפך מחוב לזכות ומטמא לטהור, ע\"י הטיית רצון שהוא ע\"י המשכה מבחי' בעל הרצון כנ\"ל, והיינו ע\"י אתכפיא ואתהפכא של בחי' נפש הבהמיות בישראל במס\"נ שבק\"ש בכל לבבך ובכל נפשך יוכל אח\"כ להתפלל ש\"ע, להיות בחי' שינוי רצון למעלה מהתורה כנ\"ל. אך מח' ודבורינו הוא גשמי לזה המלאך סנדל מקבל תפלות של ישראל ומפשיטן",[["2045","27","<b>הנה מקום אתי שהוא ית' מקומו של עולם</b>: תשא לג, כא. ב\"ר פס\"ח, ט. וראה גם ס' מאמרי אדהאמ\"צ שמות ע' קסז. דברים ח\"א ע' רצא. וש\"נ."],["2046","28","<b>וכמשל בכהאריז\"ל ע\"פ גילוי אליהו שכל העולמות הם לגבי אוא\"ס ב\"ה כטיפה בים אוקינוס</b>: ראה שער ציור העולמות (שמ\"ג) בתחילתו: שעל הכל מקיף אור הא\"ס וכל העולמות בתוכו כגרגיר חרדל בים אוקינוס. וראה גם פרדס שט\"ז פ\"ט. וראה הלשון בס' מאמרי אדהאמ\"צ נ\"ך ע' שלח: וזהו מ\"ש בכהאריז\"ל שכל ההשתלשלות הוא רק כמו טפה בים אויקיינוס ובאמת זה המאמר אמר האריז\"ל בעצמו ע\"פ רוה\"ק וגילוי אליהו כו' ולא כמו שכתבו המקובלים האחרונים שערך הביטול הוא כמו גרגיר חרדל לגבי גלגל חמה כו'."],["2047","29","<b>אורייתא מחכמה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ובכ\"מ."],["2048","30","<b>אין יסורים בלא עון</b>: שבת נה, א."],["2049","31","<b>מ\"ט פנים טמא מ\"ט פנים טהור</b>: ראה ירושל' סנהדרין פ\"ד ה\"ב."],["2050","32","<b>ב\"ש אוסרים וב\"ה מתירים ואלו ואלו דא\"ח</b>: עירובין יג, ב."]]],[2101920351,"מגשמיות לרוחניות, וקושר כתרים, היינו שמעורר למעלה לבחי' רצון העליון שלמעלה מהתורה ע\"י עבודתם באהוי\"ר וביטול אליו ית' בגוף הגשמי המורכב מאמ\"ר כנ\"ל.\nז) <b>והנה</b> אף שהמלאכים מעוררים למעלה בחי' רצון העליון שלמעלה מהתורה ע\"י ביטולם באהוי\"ר שלהם, עכ\"ז ההמשכה למטה הוא דוקא ע\"י התורה ולהמלאכים אין להם תורה, לזה הוא קושר כתרים מתפלות של ישראל דוקא, ונק' אחים ורעים לנשמות ישראל, כמו<sup data-n=\"2051\">33</sup> שמבואר שהמלאכים אין אומרים קדוש למעלה עד שישראל אומרים למטה כו'.\n<b>וזהו</b> מה יפו פעמיך בנעלים שמבואר<sup data-n=\"2052\">34</sup> במדרש דקאי בשעה שהן עולים לרגל, ולכאורה למה הם יפים בנעלים דוקא. ובכל הנ\"ל יובן, דהנה הכלל בכל עליות ממטה למעלה שגם התחתון נתעלה ואדרבה עיקר העלי' הוא מהתחתון שנתעלה בדרך כלל ע\"י מאכלים הגשמי' שאוכלים ומתהפכים לדם, נעשה מזה תוס' חיות להיות בכחו להתפלל ולמסור נפשו באחד בכל לבבך וכו'. ובפרט יש ג' מדריגות בתפלה, כמו בתחלת התפלה עליות המלכות דעשי' עד בחי' חכמה וכתר דעשי', ואח\"כ בחי' כתר דמל' דעשי' נתעלה לבחי' מל' דיצירה, ואח\"כ בחי' מל' דיצירה נתעלה לבחי' כתר שבמל' דיצירה, ואח\"כ בחי' כתר שבמל' דיצירה נתעלה לבחי' מל' דבריאה וכו' וכו' עד בחי' ש\"ע שהוא בחי' עליות לבחי' אצי', כמ\"ש ואחרי<sup data-n=\"2053\">35</sup> הרוח רעש כו' ואחרי האש קול דממה דקה תמן קאתי מלכא, שהוא בחי' ש\"ע שהוא בחשאי וכל עליות תפלות החול הוא בשבת כי בו שבת כמ\"ש עולת<sup data-n=\"2054\">36</sup> שבת וכו' כי בו שבת, ועל כל העליות שבחול ובשבת ממטה למעלה נאמר מה יפו פעמיך בנעלים דוקא, שעיקר היופי והעלי' הוא דוקא בנעלים כנ\"ל.\nח) <b>בת</b><sup data-n=\"2055\">37</sup> נדיב, בתו של אאע\"ה, פי' שבכדי שיהי' בכחינו להעלות מ\"ן לעורר בחי' רצון העליון הוא ע\"י בחי' חסד עליון הנמשך מלמעלה, כמו\"כ תקינו רבנן בכל<sup data-n=\"2056\">38</sup> הברכות לברך עובר לעשייתן ברוך אתה לנוכח הוא בחי' המשכה עילאה הבאה מלמעלה להיות בכחינו להעלות מ\"ן מלמטה, ואח\"כ אלקינו מלך העולם ל' נסתר שהוא העלאת מ\"ן מלמטה למעלה.",[["2051","33","<b>כמו שמבואר שהמלאכים אין אומרים קדוש למעלה</b>: ראה חולין צא, ב."],["2052","34","<b>שמבואר במדרש דקאי בשעה שהן עולים לרגל</b>: שהש\"ר עה\"פ. סוכה מט, ב. חגיגה ג, א."],["2053","35","<b>ואחרי הרוח רעש . . תמן קאתי מלכא</b>: מלכים א יט, יא-יב. זח\"ג רכג, ב. תקו\"ז בהקדמה (ג, ב). וראה ד\"ה ואחר הרוח בס' מאמרי אדהאמ\"צ נ\"ך ע' יד. ובכ\"מ."],["2054","36","<b>עולת שבת וכו' כי בו שבת</b>: פינחס כח, י. בראשית ב, ג."],["2055","37","<b>בת נדיב בתו של אאע\"ה</b>: שהש\"ר וסוכה וחגיגה שם."],["2056","38","<b>בכל הברכות לברך עובר לעשייתן</b>: ראה פסחים ז, ב."]]],[2101920352,"<b>חמוקי</b> יריכיך כמו חלאים מעשה ידי אמן, הוא בחי' נעל הג' שבנפש הוא ע\"י מעשה הצדקה שהוא מתן בסתר להיות התגלות בחי' סתימו דכל סתימין, והוא בחי' נעל דעשי' שבנפש שהוא ע\"י הבירורים שהוא דוקא בעשי' שמעורב טו\"ר, משא\"כ בבריאה<sup data-n=\"2057\">39</sup> רובו טוב ומיעוטו רע, וביצירה חציו טוב וחציו רע, אבל כל או\"א בפ\"ע ואינו מעורב ולזה אין שם בירורים כלל, ע\"כ ביצירה ו\"ק ז\"א מקננא ביצירה, והוא ששה מדות דאצי' שמתלבשים בבחי' נעל דיצירה, אבל בעשי' שהוא מעורב טו\"ר, כמו בעשיית המצוה יכול להיות איזה פני' שלא לש\"ש, ולזה הוא דוקא ע\"י בחי' בירור שנתברר מרע לטוב ע\"י מעשה ידי אמן כמו אומן המלבן ומצרף זהב ועפר ואדמה כו', והוא בחי' מעשה הצדקה שהוא בחי' הבירור בעסקו במו\"מ בכל היום, ונודע כי עיקר הבירור הוא בחכמה כמ\"ש<sup data-n=\"2058\">40</sup> בזהר בחכמה אתברירו, וזהו חמוקי יריכיך כי בירך יש תלת פרקין חב\"ד חג\"ת נה\"י, פרק העליון הוא נק' בגמרא בשם ירך שהוא בחי' חכמה ששם הוא עיקר הבירור, ולזה נאמר בצדקה אין<sup data-n=\"2059\">41</sup> מוסרין מעות של צדקה אלא א\"כ ממונה כו', ונגבית<sup data-n=\"2060\">42</sup> בשתים וכו' ומתחלקת בג', והוא בחי' נעל דעשי' שבנפש שהוא בחי' מל' מקננא בעשי' שהוא בחי' אופן אחד בארץ כנ\"ל.",[["2057","39","<b>בבריאה רובו טוב ומיעוטו רע</b>: ראה ע\"ח שער ק\"נ (שמ\"ט) פ\"ו. ובהמ\"מ בס' מאמרי אדהאמ\"צ בראשית ע' צז."],["2058","40","<b>כמ\"ש בזהר בחכמה אתברירו</b>: ראה זח\"ב רנד, ב. תניא אגה\"ק סכ\"ח. ובהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"ב ע' שכא."],["2059","41","<b>אין מוסרין מעות של צדקה אא\"כ ממונה כו'</b>: ב\"ב י, ב: לא יתן אדם פרוטה לארנקי של צדקה אלא א\"כ ממונה עלי' כר' חנניא בן תרדיון."],["2060","42","<b>ונגבית בשתים וכו' ומתחלקת בג'</b>: שם ח, ב: קופה של צדקה נגבית בשנים ומתחלקת בשלשה נגבית בשנים שאין עושים שררות על הצבור פחות משנים ומתחלקת בשלשה כדיני ממונות כו'."]]],[2101920353,"<h3>ענין והתהלכתי</h3>\n<b>ענין</b><sup data-n=\"2061\">1</sup> והתהלכתי<sup data-n=\"2062\">2</sup> בתוככם והייתי לכם לאלקים ואולך אתכם קוממיות וענין אחרי<sup data-n=\"2063\">3</sup> הוי' תלכו וענין באברהם כתיב התהלך<sup data-n=\"2064\">4</sup> לפני. ירידה והשפלה גדולה מאא\"ס וכוונתו ירידה צורך עלי' כו'. והנה מבואר בפרע\"ח<sup data-n=\"2065\">5</sup> שיש ב' מיני עליות, עליות בחיצוניות ועלי' בפנימיות, ועתה בזמן הזה עד ביאת משיח כל עליות בשבתות ויו\"ט הכל בבחי' פנימיות אבל לעתיד יהי' העלי' אפי' בחיצוניות וכמ\"ש ארי'<sup data-n=\"2066\">6</sup> כבקר כו' לא ירעו ולא ישחיתו כו' כי מלאה הארץ דעה, פי' כי הוא נתינת טעם מדוע ארי' כבקר, קודם<sup data-n=\"2067\">7</sup> החטא אדה\"ר שנאמר ויקרא<sup data-n=\"2068\">8</sup> אדם שמות שהעלה אותם והמשיך בהם ידיעת והכרת הבורא והראי' מחמורו<sup data-n=\"2069\">9</sup> של ר' פב\"י שנשאר<sup data-n=\"2070\">10</sup> מבהמות בה\"א שלא אכל בלי מעשר, אחמורי<sup data-n=\"2071\">11</sup> אחמרי כו' ומזאת נראה שהי' חמור בעל דעת כו' מחמת שהי' אז כל העליות אפי' בחיצוניות, וכמ\"כ יהי' לעתיד לבא בימות המשיח כו'.\n<b>והנה</b> להבין איכות הירידה והעלי' מבואר<sup data-n=\"2072\">12</sup> בע\"ח שיש חלל וסובב ועיגול וקו, והקו הוא בחי' אור והמשכה בלבד מהעיגול כו', והנה אא\"ס הוא בחי' גילוי והמשכה מעצם האור כמשל מבשרי<sup data-n=\"2073\">13</sup> אחזה כו', כמו הנשמה שמאירה להחיות את הגוף שהנשמה עצמה אינה מתלבשת רק מחמת שהיא בעצמה חיות היא מאירה חיות בגוף, וכמ\"כ שאא\"ס הוא מקור חיי החיים אשר מאיר ונמשך חיות לכל העולמות וכמ\"ש כי<sup data-n=\"2074\">14</sup> עמך מקור חיים כו' ובאורך נראה אור, נראה<sup data-n=\"2075\">15</sup> אותיות אהרן בחי' נו\"ה דאבא, כי ע\"י הקו אשר נמשך מהחלל נעשה בחי' חכמה<sup data-n=\"2076\">16</sup>",[["2061","1","<b>ענין והתהלכתי בתוככם</b>: נמצא בכת\"י 2068 (לט ד) בכותרת: תורה שנת תקע\"ב בק\"ק אולע. נוסח אחר ממאמר זה נדפס בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשסד (שם הנחת כ\"ק אדהאמ\"צ ממאמר כ\"ק אדה\"ז). וראה גם ד\"ה זה בס' מאמרי אדה\"ז עה\"ת ח\"ב ע' תרג ואילך."],["2062","2","<b>והתהלכתי בתוככם</b>: בחוקותי כו, יב-יג."],["2063","3","<b>אחרי הוי' תלכו</b>: פ' ראה יג, ה."],["2064","4","<b>התהלך לפני</b>: לך לך יז, א."],["2065","5","<b>בפרע\"ח שיש ב' מיני עליות</b>: ראה פע\"ח שער התפילה פ\"ו: ועתה בימי הגלות אפילו ביום השבת אין אנו יכולים להעלות רק הפנימית העולמות ולא חיצוניות העולמות, כי אם היו עולים חיצונית העולמות היינו רואים בעינינו עליות העולמות כו'. וראה ע\"ח שער פנימיות וחיצוניות (ש\"מ) דרוש ג' ודרוש ח'. ובכ\"מ."],["2066","6","<b>ארי' כבקר כו' לא ירעו</b>: ישעי' יא, ז. ט."],["2067","7","<b>קודם החטא</b>: כ\"ה בכת\"י המעתיק, ואוצ\"ל: כמו קודם החטא."],["2068","8","<b>ויקרא האדם שמות</b>: בראשית ב, כ. וראה גם לקו\"ת נשא כו, ב: ויקרא האדם שמות כו' להעלותן ולקשרן במקורן כו'."],["2069","9","<b>מחמורו של ר' פב\"י</b>: ראה חולין ז, א: אקלע לההוא אושפיזא רמו לי' שערי לחמרי' לא אכל כו'."],["2070","10","<b>שנשאר מבהמות בה\"א </b> [ בהררי אלף]<b></b>: ראה תהלים נ, י ותיב\"ע שם. ב\"ב עד, ב."],["2071","11","<b>אחמורי אחמרי</b>: ע\"פ לשון הגמ' ע\"ז מט, א. ועוד."],["2072","12","<b>מבואר בע\"ח שיש חלל וסובב ועיגול וקו</b>: ראה ע\"ח דרוש עגולים ויושר (ש\"א) ענף ב'. ועוד."],["2073","13","<b>מבשרי אחזה</b>: איוב יט, כו."],["2074","14","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["2075","15","<b>נראה אותיות אהרן</b>: ראה זח\"ג קג, א ובמק\"מ שם. תו\"א תצוה פב, ב. ובכ\"מ."],["2076","16","<b>חכמה ראשית הגילוי</b>: ראה זח\"א לא, ב. ס' מאמרי אדהאמ\"צ ר\"פ בראשית. ובכ\"מ."]]],[2101920354,"ראשית הגילוי והחכמה הוא בחי' מ\"ה, ומ\"ה יש בו ב' פרושים א' הוא בחי' ביטול לגמרי והב' ואנחנו<sup data-n=\"2077\">17</sup> מ\"ה שיש מי שבטל, כי החכמה הוא בחי' גוף ויש נגד אא\"ס, וכמאמר כד<sup data-n=\"2078\">18</sup> אנת תסתלק מנייהו אשתארו כולהו כגופא בלא נשמתא כי חכמה מוחא כו' חסד דרועא ימינא וכמשל היד שהוא כלי ויש גשמי נגד הרוחני היד שהוא בחי' מדת החסד, כמ\"כ בחי' מדת חסד הוא גשמי נגד עצמיות הנפש, וכן בחי' חו\"ב הם הם גשמיים וגופנים נגד עצמיות הנפש כי הנפש עצמה אינה בחי' חכמה, והראי' כאשר יאמר אדם איזה דבר שטות שאינה חכמה נאמר<sup data-n=\"2079\">19</sup> שאין לו נשמה, ועוד ראי' ממה שארז\"ל אע\"ג<sup data-n=\"2080\">20</sup> דאיהו לא חזי מזלא חזי כו', ממילא יובן שעצמיות הנפש אינה שייך כלל לבחי' החכמה ולכל שאר ספירות כי הם כולם כלים וגופנים לעצמיות הנפש, כמ\"כ למעלה כל ע\"ס הם כלים לעצמיות אא\"ס וחכמה מוחא כו' וכמו באדם שהמוח הוא הכלי להשכל כמ\"כ למעלה בחי' אנת חכים ולא בחכמה כו' הוא בחי' מוחא וכלי לאא\"ס כו'.\n<b>והנה</b> מובן כאשר רצה המאציל להיות השתלשלות העולמות הי' צריך להיות בצמצומים רבים בחי' חלל וקו עד שהמציא מציאות חכמה, ובחי' חכמה נק' בחי' יו\"ד בחי' צמצום גמור כי חכמה אין ערוך כלל לבחי' אא\"ס ע\"כ הוא צמצום יותר משארי ספירות, ואח\"כ בריבוי בחי' פרגוד ומסך שממל'<sup data-n=\"2081\">21</sup> דאצי' נעשה הכתר לבריאה וכן ממל' דבריאה נעשה כו' עד שנשתלשלו להיות מל' דמל' דעשי' ואז רגליה<sup data-n=\"2082\">22</sup> יורדות מות להתלבש בע' שרים בקליפות בחי' ותתן<sup data-n=\"2083\">23</sup> טרף כו' והיא ירידה גדולה מאא\"ס להתלבש במדריגות התחתונות כאלו ואח\"כ חוזר למקורו ונמשך מאא\"ס המשכה חדשה כדכתיב ובטובו<sup data-n=\"2084\">24</sup> מחדש בכל יום תמיד מע\"ב כי בכל יום נמשך המשכה אחרת בחי' יהי אור יהי רקיע, וכמארז\"ל<sup data-n=\"2085\">25</sup> במשנה בתענית אשר הי' קורא בתורה בכל יום מעין היום היינו ביום א' יהי אור וביום הב' יהי רקיע דהיינו שנמשך בכל יום המשכה ומוחין חדשים מא\"ס אשר לא הי' מקודם כי זהו בחי' א\"ס שיש בו עילוי אחר עילוי בבחי' א\"ס, וזהו וקדושים<sup data-n=\"2086\">26</sup> בכל יום יהללוך סלה כו' וכמו שמרע\"ה יושב בג\"ע ונהנה מזיו השכינה ומסתמא יש בזו עליות ומדריגות ולא עומד במדריגה א' וכן האבות כנ\"ל, וכמ\"כ כל ימי המעשה הם בחי' ירידה בכדי לברר בירורים וביום השבת הוא בחי' שביתה בחי' עלי' למקורו כי בשבת בורר אסור כו' ובשבוע השני נמשך המשכה",[["2077","17","<b>ואנחנו מה</b>: ע\"פ בשלח טז, ז. ח."],["2078","18","<b>כד אנת תסתלק . . חכמה מוחא . . חסד דרועא ימינא</b>: תקו\"ז בהקדמה יז א-ב."],["2079","19","<b>נאמר שאין לו נשמה</b>: בלשון תמיהה."],["2080","20","<b>אע\"ג דאיהו לא חזי</b>: מגילה ג, א."],["2081","21","<b>שממל' דאצי' נעשה הכתר לבריאה</b>: ראה ע\"ח שער העקודים (ש\"ו) פ\"ב. ועוד."],["2082","22","<b>רגליה יורדות מות</b>: משלי ה, ה."],["2083","23","<b>ותתן טרף</b>: משלי לא, טו."],["2084","24","<b>ובטובו מחדש בכל יום תמיד</b>: ברכת יוצר."],["2085","25","<b>וכמארז\"ל במשנה בתענית</b>: כו, א. וראה גמ' שם כז, ב."],["2086","26","<b>וקדושים בכל יום יהללוך סלה</b>: תפילת שמו\"ע."]]],[2101920355,"חדשה לגמרי והכל בבחי' ירידה ועלי' אתעדל\"ת ואתעדל\"ע בהעלאת מ\"ן, ומדוע צריך העלאת מ\"ן, איידי<sup data-n=\"2087\">27</sup> דטריד למבלע לא כו'.\n<b>ולהבין</b> יותר ענין ירידה צורך עלי' בהקדים ואלה<sup data-n=\"2088\">28</sup> המלכים אשר כו' שנפלו ונשברו כו' ואורות דתהו נסתלקו למעלה והכלים נשברו ונפלו למטה מטה בדברים גשמיים כמו מאכלים וכו' וכאשר אדם אוכל אותם ואח\"כ בא בכח האכילה ההוא ומתפלל ומוסר נפשו באחד הוא בחי' עלי' גדולה שמעלה הכלים למקורן הראשון וממילא נתעלה נפש האדם בעלי' יותר וד\"ל. והנה בחי' שביעית הוא בחי' שביתת הארץ בחיצוניות ג\"כ כנ\"ל כי הנה ידוע שארץ<sup data-n=\"2089\">29</sup> קדמה לשמים וסוף<sup data-n=\"2090\">30</sup> מעשה כו' ויש בה בחי' א\"ס כח הצומח שבארץ שמצמיח בבחי' א\"ס. והנה בארץ הגשמי יש ב' בחי', א' בחי' אתעדל\"ת היינו שזורע דגן או נוטע כל עץ מאכל ומצמיח הארץ, ויש<sup data-n=\"2091\">31</sup> בחי' ספיחים שצומחים מעצמם בלי אתעדל\"ת כלל בחי' זריעה, שהוא נמשך מבחי' א\"ס שלמעלה מעלה מבחי' אתעדל\"ת. והנה בשביעית כתיב שבת<sup data-n=\"2092\">32</sup> שבתון כי היא מעין והארה מבחי' עתיד שהוא למעלה מעלה מבחי' הקו שורש ומקור לכל ההשתלשלות אשר זה תלוי הכל במעשה התחתונים באתעדל\"ת אבל בחי' שביעית הוא הארת העיגול עצמו בחי' עתיד ע\"כ יש עלי' בחיצוניות ג\"כ ששבתה הארץ לגמרי, ומה גם שאפי'<sup data-n=\"2093\">33</sup> בחי' הספיחים הפקר לכל, וחיות הארץ, למעלה ממדריגות תורה אשר ע\"פ ד\"ת חייך<sup data-n=\"2094\">34</sup> קודם כו', ובפרט לבהמות וחיות ויש רק צער<sup data-n=\"2095\">35</sup> בעל חי אבל לא בחי' מזונות כמ\"ש במשנה<sup data-n=\"2096\">36</sup> אין נותנין מזונות כו' מפני שאין<sup data-n=\"2097\">37</sup> מזונותיה עליך ממילא משמע שאין מחוייב ליתן להם מזונות, ובשביעית הפקר הוא לכל חיות הארץ, וזהו מחמת שאז גילוי והארת סובב שלמעלה מעלה מהקו שתלוי בתחתונים אבל בחי' סובב העיגול הכל שווים נגדו אדם<sup data-n=\"2098\">38</sup> ובהמה כו' גדול וקטן כחשיכה<sup data-n=\"2099\">39</sup> כו', ע\"כ הוא הפקר לכל כו' והוא בחי' עלי' אפי' בחיצוניות מעין הארה דלעתיד לבא וכנ\"ל.",[["2087","27","<b>איידי דטריד למיבלע</b>: ראה חולין קח, ב. בהמ\"מ בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'קפט. וש\"נ."],["2088","28","<b>ואלה המלכים</b>: וישלח לו, לא."],["2089","29","<b>שארץ קדמה לשמים</b>: חגיגה יב, א."],["2090","30","<b>וסוף מעשה</b>: פיוט ”לכה דודי\": סוף מעשה במחשבה תחילה."],["2091","31","<b>ויש בחי' ספיחים שצומחים מעצמם</b>: ראה ג\"כ תו\"א ויגש מד, ג. לקו\"ת האזינו עח, ד. סה\"מ תקס\"ב ח\"ב ע' שלט. תקס\"ה ח\"א ע' קצח. תו\"ח ויחי קו, ב-ג."],["2092","32","<b>שבת שבתון</b>: בהר כה, ד."],["2093","33","<b>שאפי' בחי' הספיחים הפקר לכל וחיות הארץ</b>: בהר כה, ה-ז: את ספיח קצירך לא תקצור גו' ולבהמתך ולחי' אשר בארצך תהי'."],["2094","34","<b>חייך קודם</b>: ב\"מ סב, א."],["2095","35","<b>צער בעל חי</b>: בכת\"י המעתיק כאן ”נשאר בעל חי\", והוא טעות דמוכח."],["2096","36","<b>במשנה אין נותנין מזונות כו'</b>: ראה ביצה כג, ב."],["2097","37","<b>שאין מזונותי' עליך</b>: שבת קנה, ב. שו\"ע או\"ח (ודאדה\"ז) סשכ\"ד סי\"א (ס\"ז). וראה ס' מאמרי אדהאמ\"צ ויקרא שם ע' תשעג (וצע\"ק הל' שם)."],["2098","38","<b>אדם ובהמה כו'</b>: ראה לקו\"ת בהר מב, ד. וש\"נ."],["2099","39","<b>כחשיכה כו'</b>: תהלים קלט, יב."]]],[2101920356,"<b>והנה</b> בחי' תורה ומצות יש בהם ב' בחי' העלאה והמשכה, כי במצות יש ב' בחי' קדשים וקרבנות תרומות ומעשרות הם בחי' העלאות בחי' ריח ניחוח כו', ושארי מצות כמו תפילין וציצית וסוכה ולולב עם ד' מינים הם הכל בחי' המשכה מלמעלה למטה, והכל הוא בבחי' חיצוניות שנשפל המצות בדברים גשמים ובחיצוניות, והיום<sup data-n=\"2100\">40</sup> לעשותם ולמחר לקבל שכרם, דהיינו שבזמן הזה הוא בחי' עלי' וירידה הכל בחי' לעשותם בתומ\"צ ולעתיד לקבל שכרם שיהי' העלי' וירידה בחי' שכר בחיצוניות ממש עין<sup data-n=\"2101\">41</sup> בעין כו', ובתורה עצמה יש בה ג\"כ ב' בחי' הנ\"ל בחי' ירידה ועלי' כי ענין התורה במחשבה הוא בחי' עלי' שמעלה מחשבתו הגשמי לחכמה עילאה שבתורה ובמה שלומד בתורה הוא בחי' ירידה והמשכה כל<sup data-n=\"2102\">42</sup> הקורא בתורה הקב\"ה כו' וענין קריאה הוא בחי' המשכה כו' וכמארז\"ל שת\"ת<sup data-n=\"2103\">43</sup> כנגד כולם היינו כנגד כל המצות שיש בהם העלאות והמשכות ובתורה עצמה יש בה ב' הבחי' הנ\"ל העלאות והמשכות כנ\"ל.\n<b>וזהו</b> אחרי הוי' תלכו כי אחר נתינת התורה קרוב ונקל להיות בחי' הליכה בחי' הלוך ושוב עליי' וירידה, כי מאחר שירד ה' על הר סיני ונמשך אא\"ס בדברים תחתונים כמו במצות ת\"ת ע\"כ בנקל יכול להיות רו\"ש למטה בבחי' חיצוניות בבחי' עלי' לבד בחי' חיצוניות.\n<b>והנה</b> באדם יש ג\"כ בחי' עלי' וירידה אבל הכל בבחי' פנימיות בבחי' עבודה שבלב בחי' מס\"נ רו\"ש ויוכל לבוא למדריגה גבוה יותר מבחי' התורה, כי עפ\"י התורה הכל הוא בצדק ובמשפט לשלם כפעלו אבל בתפלה יכול לבוא למדריגה גבוה יותר, וזה שאנו מברכין יהי רצון, רצון חדש וחנון ומרבה לסלוח כו' שבחי' סליחה היא מעלה במקום שאין אתעדל\"ת מגיע לשם ע\"כ הוא יכול למחול כו' והוא למעלה מבחי' התורה. וזהו זאת<sup data-n=\"2104\">44</sup> תורת האדם אשר יעשה אותם וחי בהם, שמה שתורה עושה הוא בבחי' חיצוניות אבל אדם עושה בבחי' פנימיות כו', וכמ\"כ למעלה בחי' עלי' וירידה בחי' עלי' והאופנים ברעש גדול כו', ואח\"כ הם עומדים בחי' שתיקה בחי' המשכה כנ\"ל. והנה כתיב אופן<sup data-n=\"2105\">45</sup> א' בארץ כו' וזהו סנדל<sup data-n=\"2106\">46</sup> קושר כתרים כו' כי סנדלפ' בחי' כלי וביטול לגמרי, וקושר כתרים להיות כתר לתחתון בחי' המשכה מלמעלה למטה כו'. אבל באברהם כתיב התהלך לפני והיה תמים בחי' הליכה שהוא עלי' וירידה בפנימיות, כי אברהם לא קיבל את התורה ע\"כ הילוכו הי' בבחי' פנימיות לבד.",[["2100","40","<b>והיום לעשותם ולמחר לקבל שכרם</b>: ואתחנן ז, יא. עירובין כב, א."],["2101","41","<b>עין בעין</b>: ישעי' נב, ח."],["2102","42","<b>כל הקורא בתורה הקב\"ה כו'</b>: תדא\"ר רפי\"ח. ילקו\"ש איכה רמז תתרלד."],["2103","43","<b>שת\"ת כנגד כולם</b>: ריש מס' פאה."],["2104","44","<b>זאת תורת האדם אשר יעשה אותם וחי בהם</b>: ע\"פ שמואל ב ז, יט. אחרי יח, ה."],["2105","45","<b>אופן א' בארץ</b>: יחזקאל א, טו."],["2106","46","<b>סנדל קושר כתרים</b>: ראה זח\"א וישלח קסז, ב. וראה סה\"מ תרנ\"ז ר\"ע שלח. סה\"מ תש\"ח ע' 202. וש\"נ."]]],[2101920357,"<b>והנה</b> אברהם הוא בחי' רב חסד, כי אית<sup data-n=\"2107\">47</sup> חסד כו' אם<sup data-n=\"2108\">48</sup> הבנים אשר נמשך החסד עפ\"י השכל למי שראוי כו', ויש בחי' רב חסד בחי' טבע החסד לעשות חסד עם כולם וגם לא עפ\"י השכל כי עפ\"י התורה אינו<sup data-n=\"2109\">49</sup> צריך ליתן יותר מחומש ממעותיו, ואברהם לוה מעות ונתן צדקה כדאיתא<sup data-n=\"2110\">50</sup> בחזרה פרע חובותיו אשר זה המדה לעשות חסד כזה אינה עפ\"י התורה אלא שמדרגתו מבחי' רב חסד גרם למעלה למשוך אא\"ס להיות בחי' חכמה, כי אבא<sup data-n=\"2111\">51</sup> יונק ממזל הח' כי מזלות הם בחי' שערות, והנה שערות הם לפי הנראה נמשכים מבחי' חיצוניות, והראי' שיוכל לחתוך אותם ואינם שייכים לגמרי לעצם, אעפי\"כ באמת נמשכין מבחי' פנימיות המוחין, והראי' שסריס<sup data-n=\"2112\">52</sup> אין לו זקן כי מחמת שאין לו כח המוליד ע\"כ אין לו שערות בחי' זקן כי כח המוליד הוא בבחי' א\"ס כי הוא יכול להוליד דור אחר דור עד אין קץ כו' וכאשר אין לו כח המוליד אזי אין לו שערות ג\"כ וממילא מובן ששערות הם מבחי' א\"ס, ע\"כ אברהם ע\"י בחי' רב חסד הוא המשיך נוצר חסד שהוא מזל הח' המשיך להיות בחי' חכמה כמ\"ש נוצר<sup data-n=\"2113\">53</sup> חסד לאלפים שהוא ב' אלפים אאלפך<sup data-n=\"2114\">54</sup> חכמה אאלפך בינה כי אבא יונק ממזל הח' ואימא ממזל הי\"ג, ע\"כ שהוא מבחי' ורב חסד המשיך בחי' המזלות נוצר חסד לאלפים, וזהו אברם<sup data-n=\"2115\">55</sup> אינו מוליד אבל אברהם כו', כי<sup data-n=\"2116\">56</sup> אברם בחי' א\"ב ר\"ם בחי' אב אבל הוא רם שהוא בחי' שלמעלה מהשתלשלות העולמות שא\"א להיות בחי' הולדה, פי' שאברם הוא רק בחי' המשכה מא\"ס שיהיו או\"א תרין רעין כו' בבחי' תרין עטרין אבל לא בחי' הולדת מוחין חדשים שיהי' בחי' בן ובת וד\"ל.\n<b>אבל</b> כאשר ניתוסף לו הה\"א ע\"י המצות מילה שניתנה קודם מ\"ת ולכן הי' בו כח המוליד בחו\"ב שהיא בחי' השתלשלות הליכה שמלמעלה למטה ומלמטה למעלה בחי' עלי' וירידה אבל הכל בבחי' פנימיות, וזהו התהלך לפני והי' תמים היינו בחי' הה\"א בחי' ברית היינו בחי' מילה שהוא כח המוליד, וזהו עבודה גדולה לבוא לבחי' זו מחמת שלא הי' עדיין בחי' תו\"מ, אבל כאשר נתן",[["2107","47","<b>אית חסד כו'</b>: זח\"א ריט, א. זח\"ג כא, א. קלג, ב. קמ, ב."],["2108","48","<b>אם הבנים</b>: ע\"פ תהלים קיג, ט (ואולי יש כאן איזה טעות מעתיק, או שחסר כמה תיבות)."],["2109","49","<b>אינו צריך ליתן יותר מחומש ממעותיו</b>: כתובות נ, א."],["2110","50","<b>כדאיתא בחזרה פרע מעותיו</b>: ב\"ר פמ\"א, ג: וילך למסעיו במסעות שהלך בהן חזר כו' הלך לפרוע הקפותיו."],["2111","51","<b>אבא יונק ממזל הח'</b>: ראה זח\"ג רפט, ב. ע\"ח שער הכללים פ\"ה. ובכ\"מ."],["2112","52","<b>שסריס אין לו זקן</b>: יבמות פ, ב."],["2113","53","<b>נוצר חסד לאלפים</b>: תשא לד, ז."],["2114","54","<b>אאלפך חכמה אאלפך בינה</b>: איוב לג, לג. שבת קד, א."],["2115","55","<b>אברם אינו מוליד</b>: ב\"ר פמ\"ד, י."],["2116","56","<b>כי אברם בחי' א\"ב ר\"ם</b>: ראה גם תו\"א לך לך יא, א. תו\"ח לך לך פ, א. חיי\"ש קכא, ד. אוה\"ת לך לך כרך ד' תרפה, א. ובכ\"מ."]]],[2101920358,"לנו התורה והמשיך אא\"ס בדרך עלי' וירידה בחיצוניות עשי' אזי קרוב ונקל לבוא למדריגה פנימיות עלי' כנ\"ל.\n<b>וזהו</b> אחרי שאנו מתעטפים בטלית ותפילין בקל יותר לבוא למדריגות עליות וירידות שבתפילה בחי' רו\"ש היינו וימינו תחבקני שהיא התורה, ואנכי<sup data-n=\"2117\">57</sup> תרגלתי לאפרים קחם על זרועותיו בחי' חיצוניות בכדי להגביה שיבוא למדריגת עלי' וירידה בפנימיות וזהו אחרי הוי' תלכו כו' וד\"ל.\n<b>וזהו</b> היום לעשותם אבל לעתיד לקבל שכרם ויהי' גילוי אמיתי עליות וירידות בבחי' החיצוניות שעין בעין יראו וכו' שגם גוף הגשמי נהנין מזיו כו', כי אז יהי' גילוי מהסובב אשר למעלה מעלה מהשתלשלות אשר אצלו שווים קטן וגדול גשמי' ורוחניות.\n<b>וזהו</b> בחי' והתהלכתי בתוככם, כי פי' והתהלכתי הוא עצמיות א\"ס אשר למעלה מהשתלשלות יהי' נמשך בבחי' הליכה עלי' וירידה, כי לעתיד יהי' ג\"כ תורה ועלי' וירידה גם חול ושבת רו\"ש היינו ממטה למעלה ומלמעלה למטה אבל הכל מבחי' עצמיות א\"ס, אעפי\"כ יהי' בתוככם שיהי' הזדככות גדולה שהנשמות והגופים יהיו כלים לבחי' עצמיות א\"ס, וזהו והייתי לכם לאלקים כי יש בחי' אלקים שמדרגתו גדולה מבחי' הוי' ואז יהי' בחי' אלקים הנ\"ל, וזהו ואולך אתכם קוממיות<sup data-n=\"2118\">58</sup> שני קומות חיצוני' ופנימיו' כי אז יהי' הגילוי גם בחיצוני' ממש כנ\"ל.",[["2117","57","<b>ואנכי תרגלתי . . קחם על זרועותיו</b>: הושע יא, ג."],["2118","58","<b>קוממיות שני קומות</b>: ראה ב\"ב עה, א. סנהדרין ק, א."]]],[2101920359,"<h3>להבין ענין השבת</h3>\n<b>להבין</b><sup data-n=\"2119\">1</sup> ענין השבת ע\"פ מ\"ש כי<sup data-n=\"2120\">2</sup> בו שבת מכל מלאכתו אשר ברא כו' לעשות. יובן<sup data-n=\"2121\">3</sup> בהקדים ענין העשיי' מהו, דכמו שבנפש עד\"מ יש ג' לבושים מודו\"מ כי כח התנועה שמתפשט מהיד עד\"מ בזריקת אבן להוליכו באויר הרי הוא כח מהנפש אלא שהוא כח חיצוני, וכח הדבור שבה' מוצאו' המבטא הוא פנימי יותר, למעלה הימנו כח המחשבה וכולם הם לבושי הנפש, וככה יובן למעלה עם היות כי<sup data-n=\"2122\">4</sup> לא מחשבותי מחשבותיכם כתי', וכן מסתמא בדיבור ובמעשה כי דברו אשר יצא מפיו לא ישוב ריקם כדיבור האדם, מ\"מ נוכל להבין עד\"מ ענין מו\"ד שהם בחי' לבושי' דהיינו כשאמר ה' יהי<sup data-n=\"2123\">5</sup> אור שהוא בחי' צירופי אותיו' הדבור הנה מתחלה היו מציאו' אותיו' אלו במחשב' ונברא מהם האור בעלמין סתימין כו' וכשנתגלה בדבור נברא אור שלנו וכן עד\"ז ביהי<sup data-n=\"2124\">6</sup> רקיע מתחלה נברא הרקיע העליון הנמתח על ראשי הנשמו' בג\"ע כדאי' בזהר ונמשך מאותיו' מחשבתו ית' וכשנתגלו אותיו' אלו בדבור נברא הרקיע שלנו אלא שנוסף בו עוד ויעש<sup data-n=\"2125\">7</sup> ה' אלקים את הרקיע דהיינו ע\"י כח הג' מן הלבושי' שהוא כח העשי' לעשות גשמיות הרקיע, וכח זה הוא היותר אחרון ולמטה במדרגה מב' הכחות מו\"ד וכמ\"ש בו אף<sup data-n=\"2126\">8</sup> עשיתיו הבדיל הענין בינו ליצירה כו'.\n<b>והנה</b> לעולם<sup data-n=\"2127\">9</sup> דברך ה' נצב בשמי' כתי' גם עתה ומחדש<sup data-n=\"2128\">10</sup> בכל יום תמיד מע\"ב וגם בשבת אין האותיו' מסתלקי' ח\"ו שאילו כן הי' העולם חוזר לתהו כו' אלא שמ\"מ נק' שבת מל' שביתה מן הצמצומי' הנ\"ל שבחול מחמת גלוי תענוג העליון כדכתי' ויכולו<sup data-n=\"2129\">11</sup> השמים והארץ כו' ויכולו ל' פועל יוצא שהוא ית' מקבל",[["2119","1","<b>להבין ענין השבת</b>: נדפס כאן מגוכי\"ק הצ\"צ בס' תקע\"ב [מס' 1116]. והוא ביאור לד\"ה ויהיו בנ\"י במדבר וימצאו איש מקושש עצים (בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'רמ. ונוסח אחר באוה\"ת שלח ע' 92, ובהוצאת אוה\"ת הקודמת הוא בכרך ו' ע' א'תתיד). ונמצא ג\"כ בס' מאמרי אדה\"ז עה\"ת ח\"א ע' יא. ובשינויים בס' מאמרי אדהאמ\"צ במדבר ח\"ג ע' א'רנד. אוה\"ת שלח ע' 99 [ובהוצאה הקודמת של האוה\"ת הוא בכרך ה' ע' א'תרג]. סה\"מ תרל\"ג ח\"ב ע' שלח. וראה המשך מים רבים תרל\"ו פקע\"ח (ובסופו שם כותב: כן פי' רבינו ז\"ל בד\"ה מקושש דתקע\"ב)."],["2120","2","<b>כי בו שבת</b>: בראשית ב, ג."],["2121","3","<b>יובן בהקדים ענין העשיי' מהו</b>: ראה בכ\"ז גם בלקו\"ת ש\"ש סו, ב. סה\"מ תרכ\"ו (הוצאת תשמ\"ט) ע' רפא ואילך [ובהנסמן לשם בתחילת הספר]."],["2122","4","<b>כי לא מחשבותי מחשבותיכם . . דברו אשר יצא מפיו</b>: ע\"פ ישעי' נה, ח ואילך."],["2123","5","<b>יהי אור</b>: בראשית א, ג."],["2124","6","<b>ביהי רקיע . . הרקיע העליון הנמתח על ראשי הנשמו' בג\"ע כדאי' בזהר</b>: בראשית א, ו. ראה זח\"ב קל, ב. קלו, א. רט, ב ואילך. תניא שעהיחוה\"א פ\"ה. וראה בליקוט פירושים ומ\"מ לשם (חיטריק) ע' קלב וע' קמד."],["2125","7","<b>ויעש ה' אלקים את הרקיע</b>: ע\"פ בראשית שם, ז."],["2126","8","<b>אף עשיתיו</b>: ישעי' מג, ז. וראה גם לקו\"ת בלק סז, א ואילך."],["2127","9","<b>לעולם דברך ה' נצב בשמים</b>: ע\"פ תהלים קיט, פט."],["2128","10","<b>ומחדש בכל יום תמיד מע\"ב</b>: נוסח ברכת יוצר."],["2129","11","<b>ויכולו השמים והארץ</b>: בראשית ב, א."]]],[2101920360,"תענוג ונח\"ר ממלאכתו אשר עשה איך ומה שהי' כוונת הבריאה. וז\"ש ממלאכתו אשר ברא לעשות, כלומר לא ששובת מן העשי' לגמרי אלא ששובת מן הצמצומי' שהי' תחלה מבחי' אשר ברא ע\"י ש' אלקים עד שיהי' בבחי' לעשות כו', דהיינו עד\"מ אדם הפוסק מעשיית דבר מלאכת עבודה שאזי השכל והמחשבה שהיו נשפלי' תחלה בעשיי' המלאכה מתכללי' ועולי' בעצמותם, ולכן שבת<sup data-n=\"2130\">12</sup> אותיו' תשב, ואז הוא גילוי התענוג בחי' סעודתא<sup data-n=\"2131\">13</sup> דע\"ק שעתיק הוא מקור התענוגי'. והנה כתי' ושמרו<sup data-n=\"2132\">14</sup> בנ\"י לעשות את השבת הגם דשבת<sup data-n=\"2133\">15</sup> מיקדשא וקיימא שלכן אין אומרי' בשבת ותתן לנו כו', אבל להיות השבת לדורותם שיתגלה מטה מטה להיות דר ביניהם, וגם לדורותם כפשוטו ל' נצחיית היינו שיתגלה מלמעלה מהזמן בזמן, כי בחי' השבת הוא עליי' בלמעלה מהזמן שלכן מוני' גם עכשיו כל יום שאחר השבת יום ראשון ואח\"כ יום ב' כו' הגם שכבר עברו עידן<sup data-n=\"2134\">16</sup> עדני' אלא משום שכל שבת הוא באמת עליי' בלמעלה מהזמן, וההמשכה זו בבחי' זמן הוא ע\"י ישראל מי<sup data-n=\"2135\">17</sup> שטרח בע\"ש כו'.\n<b>ויש</b> בזה ב' בחי' א' ע\"י רעש גדול דנפש הבהמית ששרשו מאופני' המתנשאי' ברעש גדול, ועיקר הרעש הוא מחמת כי קק\"ק<sup data-n=\"2136\">18</sup> הוי' צבאות שמחי' צבאי צבאות עליוני' ותחתוני' ואעפ\"כ הוא בעצמו קדוש ומובדל כו', וב' ע\"י ביטול היש דהיינו בכל מעשה המצות כמו צדקה שהנותן שהוא יש משפיע לעני האי\"ן דלית לי' מגרמי' כו', ובאתעדל\"ת אתעדל\"ע נמשך גלוי אא\"ס ב\"ה בשבת, והגילוי הוא בב' בחי' מקיפי' ופנימיי', ע\"י ביטול היש לאין גילוי פנימי' וע\"י רעש גדול בחי' א\"ס גילוי מקיפי'. ודרך פרט התפלה עצמה כלולה משתי הבחי' שלהיו' כח להתפלל הוא מבירורי מאכלי' שנהפכי' לדם בלב שבו תלוי החיו' וכל ל\"ט מלאכו' הזורע וחורש<sup data-n=\"2137\">19</sup> כו' כולם המה לתועלת זה מזון ומשתה ולבוש להגין על הדם שלא יתקלקל כמו שלא יתקרר כו' והוא בחי' פנימי', ומה שאעפ\"כ הוא ברעש גדול כח א\"ס בחי' מקיפים כו'.",[["2130","12","<b>שבת אותיו' תשב</b>: ראה תניא אגה\"ת ספ\"י (ובס' תניא מהדו\"ק — ע' תקלא), ובהנסמן לשם."],["2131","13","<b>סעודתא דע\"ק</b>: ע\"פ זח\"ב פח, א. ובכ\"מ."],["2132","14","<b>ושמרו בנ\"י לעשות את השבת</b>: ע\"פ תשא לא, טז."],["2133","15","<b>דשבת מיקדשא וקיימא</b>: ביצה יז, א."],["2134","16","<b>עידן עדני'</b>: לשון הכתוב — דניאל ז, כה."],["2135","17","<b>מי שטרח בע\"ש כו'</b>: ע\"ז ג, א."],["2136","18","<b>קק\"ק הוי' צבאות</b>: ישעי' ו, ג."],["2137","19","<b>הזורע וחורש כו'</b>: ע\"פ שבת עג, א."]]],[2101920361,"<b>בשבת</b> שברח אדמו\"ר מצרפת שנת תקע\"ב בלאדי בשעת מלחמה עם מלך רוסיא."],[2101920362,"<h3>הנה גלות ישראל</h3>\n<b>הנה</b><sup data-n=\"2138\">1</sup> גלות ישראל באוה\"ע לברר<sup data-n=\"2139\">2</sup> רפ\"ח ניצוצין כו' א\"כ במצרים שעבדו בחומר ובלבנים ובררו מהר ויצאו לחרות, וכמו\"כ עתה בגלותנו בראשונה תחת ממשלת פולין הוא עשו<sup data-n=\"2140\">3</sup> הוא אדום על<sup data-n=\"2141\">4</sup> חרבך תחי' היו מתעללים בעלילות שקרים לישראל והיו הורגים על כל עלילה לישראל, וביררו מהר והעבירו ממשלתם, ועכשיו תחת ממשלת יון שהוא גבורה שבחסד וראי' מנגון<sup data-n=\"2142\">5</sup> יון וישמעאל, ושר של יון מלעיג מהם ואומר אתם שעבדתם את ישראל בכבדות ובררו מהר ויצאו להם, אני לא כן שוטה כמוכם, אני לא אכביד עליהם רק מעט מעט ולא יבררו מהר וביני לביני אאריך את הגלות. וגם ידוע לי\"ח ע\"פ ניגון יון וישמעאל, יון הוא בטבעו כנ\"ל, ומנגן בגבורה בשמחה, וישמעאל הוא חסד שבגבורה מנגן מרורות למו, וחסדו אך בוראה לאיש שא\"צ לחסדו שונאהו שנאה גמורה עד שיקח כידון לדקרו ודי לי\"ח, וגם המלוכה<sup data-n=\"2143\">6</sup> דיון מתנהג ע\"פ סוד כו' וד\"ל.",[["2138","1","<b>הנה גלות ישראל</b>: נדפס בס' מגדל עז (כפ\"ח תש\"מ) בע' תנד. ובמאמרי אדה\"ז ענינים ע' קה. וראה עוד להלן בהוספות ברשימת הכת\"י ע\"ד הכותרת כאן: בשבת שברח כו'.\nלכללות המאמר ראה ג\"כ ד\"ה עוד ענין התחלקות המדות של האומות — הנד' בס' מאמרי אדה\"ז הקצרים ע' תלח (ובס' מגדל עז שם). וש\"נ.\nהציונים דלקמן נעתקו (בשינויים קלים) מס' מגדל עז שם."],["2139","2","<b>לברר רפ\"ח נצוצין</b>: ראה תו\"א וישב כז, ד. תו\"ח שמות נב, א ואילך. ובכ\"מ."],["2140","3","<b>עשו הוא אדום</b>: בראשית לו, א. וראה המבוא בקב-הישר (בהוצאות שהפרק בשלימותו) שמלכות פולין היא אדום."],["2141","4","<b>על חרבך תחי'</b>: שם כז, מ."],["2142","5","<b>מנגון יון וישמעאל</b>: ראה ס' מאמרי אדה\"ז על פרשיות התורה (בראשית-שמות) ע' רמח. סה\"מ תקס\"ג ע' רז ואילך (הובא ג\"כ ביהל אור ע' שעג). שערי תשובה לאדהאמ\"צ ח\"ב טו, ד ואילך. תו\"ח תצוה תקכ, ב. אוה\"ת בראשית חיי\"ש תשצג, א. (וראה מ\"ש ר\"מ די-לונזאנו ב”שתי ידות\" (סה, ב)."],["2143","6","<b>המלוכה דיון מתנהג ע\"פ סוד</b>: בד\"ה עוד ענין התחלקות המדות (הנ\"ל בריש המאמר): ויון הם בחי' יסוד התקשרות. ע\"ש."]]]]});
